/** Original procedural compositions for this simulator; no samples or external audio.
 * The score is authored below as MIDI notes, not generated by a remote service.
 * Call unlock from a trusted interaction and sync after visibility/preferences change.
 */

const LOOKAHEAD_MS = 100;
const SCHEDULE_AHEAD = 0.3;
const MAX_VOICES = 16;
const MASTER_LEVEL = 0.2;

function makeScore(bpm, chords, melodies, bright = false) {
  const events = [];
  chords.forEach((notes, bar) => {
    events.push({ beat: bar * 4, notes, length: 3.7, pad: true });
    melodies[bar].forEach(([offset, note, length = 0.55]) => {
      events.push({ beat: bar * 4 + offset, notes: [note], length, pad: false });
    });
  });
  events.sort((left, right) => left.beat - right.beat);
  return { bpm, bright, beats: chords.length * 4, events };
}

// A quiet, sixty-second C-major / A-minor cycle with spacious upper notes.
const ambient = makeScore(64, [
  [48, 55, 64], [45, 52, 60], [41, 48, 57], [43, 50, 59],
  [40, 47, 55], [45, 52, 59], [41, 48, 55], [43, 50, 60],
  [48, 55, 62], [45, 52, 60], [41, 48, 57], [43, 50, 59],
  [40, 47, 55], [45, 52, 60], [41, 48, 57], [43, 50, 59],
], [
  [[0.5, 76], [2.5, 79]], [[1, 72]], [[0.5, 69], [2.5, 72]], [[1.5, 74]],
  [[0.5, 71], [2.5, 67]], [[1, 71]], [[0.5, 72], [2.5, 69]], [[1.5, 74]],
  [[0.5, 79], [2.5, 76]], [[1, 72]], [[0.5, 69], [2.5, 76]], [[1.5, 74]],
  [[0.5, 71], [2.5, 67]], [[1, 72]], [[0.5, 69], [2.5, 72]], [[1.5, 71], [3, 74]],
]);

// A separate, brighter closing theme: rising phrases followed by a calm cadence.
const finale = makeScore(68, [
  [48, 60, 67], [43, 59, 62], [45, 60, 64], [41, 57, 64],
  [48, 60, 67], [41, 57, 60], [43, 59, 62], [48, 55, 64],
  [48, 60, 67], [43, 59, 62], [45, 60, 64], [41, 57, 64],
  [40, 55, 59], [41, 57, 60], [43, 59, 62], [48, 55, 64],
], [
  [[0, 76], [1, 79], [2, 81], [3, 79]], [[0, 74], [1.5, 71], [3, 74]],
  [[0, 76], [1, 72], [2, 76], [3, 79]], [[0, 77], [1.5, 76], [3, 72]],
  [[0, 79], [1, 76], [2, 72], [3, 76]], [[0, 77], [1.5, 76], [3, 72]],
  [[0, 74], [1, 71], [2, 74], [3, 79]], [[0, 76], [1.5, 72, 1.5]],
  [[0, 76], [1, 79], [2, 84], [3, 79]], [[0, 74], [1.5, 71], [3, 74]],
  [[0, 76], [1, 79], [2, 81], [3, 76]], [[0, 77], [1.5, 76], [3, 72]],
  [[0, 71], [1, 74], [2, 76], [3, 74]], [[0, 72], [1.5, 69], [3, 72]],
  [[0, 74], [1, 71], [2, 67], [3, 71]], [[0, 72, 2.2]],
], true);

const scores = { ambient, finale };
const frequency = midi => 440 * 2 ** ((midi - 69) / 12);

export function createMusicPlayer(getPreferences, environment = globalThis) {
  let context = null;
  let master = null;
  let scene = null;
  let unlocked = false;
  let desiredPlaying = false;
  let generation = 0;
  let timer = null;
  let playingScene = null;
  let resumeOperation = null;
  let suspendOperation = null;
  let eventIndex = 0;
  let cycleStart = 0;
  let lastVolume = null;
  const voices = new Set();
  const scheduleTimer = callback => environment.setTimeout(callback, LOOKAHEAD_MS);

  function preferences() {
    try {
      const value = getPreferences() || {};
      return {
        enabled: value.musicEnabled === true,
        volume: typeof value.musicVolume === 'number' && Number.isFinite(value.musicVolume)
          ? Math.max(0, Math.min(100, value.musicVolume)) : 0,
      };
    } catch { return { enabled: false, volume: 0 }; }
  }

  function permitted() {
    const prefs = preferences();
    return unlocked && Boolean(scene) && prefs.enabled && prefs.volume > 0 && !environment.document?.hidden;
  }

  function updateVolume(immediate = false) {
    if (!context || !master) return;
    const target = desiredPlaying ? MASTER_LEVEL * preferences().volume / 100 : 0;
    if (lastVolume === target && !immediate) return;
    const at = context.currentTime;
    master.gain.cancelScheduledValues(at);
    if (immediate) master.gain.setValueAtTime(target, at);
    else if (typeof master.gain.setTargetAtTime === 'function') master.gain.setTargetAtTime(target, at, 0.08);
    else {
      master.gain.setValueAtTime(master.gain.value, at);
      master.gain.linearRampToValueAtTime(target, at + 0.15);
    }
    lastVolume = target;
  }

  function disposeVoice(voice, stop = false) {
    voices.delete(voice);
    if (stop) { try { voice.source.stop(context.currentTime); } catch { /* Already ended. */ } }
    try { voice.source.disconnect(); } catch { /* Already disconnected. */ }
    try { voice.gain.disconnect(); } catch { /* Already disconnected. */ }
  }

  function clearPlayback() {
    if (timer !== null) { environment.clearTimeout(timer); timer = null; }
    for (const voice of [...voices]) disposeVoice(voice, true);
    playingScene = null;
    updateVolume(true);
  }

  function suspendContext() {
    if (!context || context.state === 'closed') return Promise.resolve(false);
    if (suspendOperation) return suspendOperation.promise;
    const operation = {};
    suspendOperation = operation;
    try {
      // Also queue a suspend while resume is pending; state may still be suspended.
      operation.promise = Promise.resolve(context.suspend()).then(() => true, () => false).finally(() => {
        if (suspendOperation === operation) suspendOperation = null;
      });
    } catch {
      suspendOperation = null;
      operation.promise = Promise.resolve(false);
    }
    return operation.promise;
  }

  function stop() {
    generation += 1;
    desiredPlaying = false;
    clearPlayback();
    void suspendContext();
  }

  async function settleSilent() {
    if (desiredPlaying && permitted()) return;
    await suspendContext();
    // A pending suspend can resolve before an older resume turns the context
    // running. Its promise must settle before issuing a fresh suspend request.
    if ((!desiredPlaying || !permitted()) && context?.state === 'running') await suspendContext();
  }

  function ensureContext() {
    if (context && context.state !== 'closed') return true;
    const AudioContext = environment.AudioContext || environment.webkitAudioContext;
    if (!AudioContext) return false;
    try {
      context = new AudioContext();
      master = context.createGain();
      master.gain.setValueAtTime(0, context.currentTime);
      master.connect(context.destination);
      lastVolume = 0;
      return true;
    } catch {
      context = null;
      master = null;
      return false;
    }
  }

  function playNote(note, at, length, pad, bright, index) {
    if (voices.size >= MAX_VOICES) return;
    const source = context.createOscillator();
    const gain = context.createGain();
    source.type = pad && index === 1 ? 'triangle' : 'sine';
    source.frequency.setValueAtTime(frequency(note), at);
    const attack = pad ? 0.85 : 0.045;
    const release = pad ? 1.1 : 0.5;
    const level = pad ? (index === 1 ? 0.075 : 0.1) : bright ? 0.13 : 0.095;
    const end = at + Math.max(attack + 0.02, length) + release;
    gain.gain.setValueAtTime(0, at);
    gain.gain.linearRampToValueAtTime(level, at + attack);
    gain.gain.setValueAtTime(level, end - release);
    gain.gain.linearRampToValueAtTime(0, end);
    source.connect(gain);
    gain.connect(master);
    const voice = { source, gain, end };
    voices.add(voice);
    source.onended = () => disposeVoice(voice);
    source.start(at);
    source.stop(end + 0.02);
  }

  function tick(token) {
    if (token !== generation || !desiredPlaying) return;
    timer = null;
    if (!permitted()) { stop(); return; }
    if (context.state !== 'running') { stop(); return; }
    try {
      updateVolume();
      const score = scores[playingScene];
      const beatDuration = 60 / score.bpm;
      const now = context.currentTime;
      for (const voice of [...voices]) if (voice.end + 0.02 < now) disposeVoice(voice);
      // Do not replay missed bars after a throttled tab or a long main-thread pause.
      if (cycleStart + score.events[eventIndex].beat * beatDuration < now - SCHEDULE_AHEAD) {
        eventIndex = 0;
        cycleStart = now + 0.045;
      }
      while (cycleStart + score.events[eventIndex].beat * beatDuration < now + SCHEDULE_AHEAD) {
        const event = score.events[eventIndex];
        const at = Math.max(now + 0.005, cycleStart + event.beat * beatDuration);
        event.notes.forEach((note, index) => playNote(note, at, event.length * beatDuration, event.pad, score.bright, index));
        eventIndex += 1;
        if (eventIndex === score.events.length) { eventIndex = 0; cycleStart += score.beats * beatDuration; }
      }
      if (token === generation && desiredPlaying) timer = scheduleTimer(() => tick(token));
    } catch { stop(); }
  }

  function beginPlayback(token) {
    if (token !== generation || !desiredPlaying || !permitted() || context.state !== 'running') return false;
    if (playingScene === scene && timer !== null) { updateVolume(); return true; }
    playingScene = scene;
    eventIndex = 0;
    cycleStart = context.currentTime + 0.045;
    updateVolume();
    tick(token);
    return playingScene === scene && timer !== null;
  }

  function resumeFor(token, force = false) {
    if (resumeOperation?.token === token) return resumeOperation.promise;
    if (!force && context.state === 'running' && !suspendOperation) return Promise.resolve(beginPlayback(token));
    const operation = { token };
    resumeOperation = operation;
    const pendingSuspend = suspendOperation?.promise;
    try {
      // Deliberately called synchronously, before the first await, for autoplay rules.
      const resumed = context.resume();
      operation.promise = Promise.resolve(resumed).then(async () => {
        if (token !== generation || !desiredPlaying || !permitted()) {
          if (!desiredPlaying || !permitted()) await settleSilent();
          return false;
        }
        // An older suspend must settle before a newer run starts scheduling notes.
        if (pendingSuspend) await pendingSuspend;
        if (token !== generation || !desiredPlaying || !permitted()) {
          if (!desiredPlaying || !permitted()) await settleSilent();
          return false;
        }
        if (context.state !== 'running') await context.resume();
        if (token !== generation || !desiredPlaying || !permitted()) {
          if (!desiredPlaying || !permitted()) await settleSilent();
          return false;
        }
        return beginPlayback(token);
      }).catch(() => {
        if (token === generation) stop();
        return false;
      }).finally(() => {
        if (resumeOperation === operation) resumeOperation = null;
      });
    } catch {
      resumeOperation = null;
      if (token === generation) stop();
      operation.promise = Promise.resolve(false);
    }
    return operation.promise;
  }

  function sync() {
    if (!permitted() || !context || context.state === 'closed') {
      if (desiredPlaying || playingScene || timer !== null || voices.size) stop();
      return Promise.resolve(false);
    }
    desiredPlaying = true;
    return resumeFor(generation);
  }

  function setScene(nextScene) {
    const next = nextScene === 'ambient' || nextScene === 'finale' ? nextScene : null;
    if (scene !== next) {
      scene = next;
      stop();
    }
    return sync();
  }

  function unlock() {
    unlocked = true;
    if (!ensureContext()) return Promise.resolve(false);
    const allowed = permitted();
    if (!allowed && desiredPlaying) stop();
    desiredPlaying = allowed;
    // Even when music is off, a trusted gesture may unlock the reusable context.
    // No oscillators are created until a scene, preference and visibility allow it.
    return resumeFor(generation, !allowed);
  }

  return { unlock, setScene, sync, stop };
}
